'addons/fleet_base/models/vehicle.py':"from odoo import models, fields, api\nfrom odoo.exceptions import ValidationError\n\nclass Vehicle(models.Model):\n    _name = 'fleet.vehicle.x'\n    _inherit = ['mail.thread']\n    _description = 'Vehicle'\n    name = fields.Char(required=True, size=64)\n    plate = fields.Char(required=True)\n    driver_id = fields.Many2one('res.partner')\n    _sql_constraints = [('plate_uniq', 'unique(plate)', 'Plate must be unique')]\n\n    @api.constrains('plate')\n    def _check_plate(self):\n        if not self.plate: raise ValidationError('Plate is required')\n",
