'addons/fleet_base/security/fleet_security.xml':'<odoo><record id="group_fleet_manager" model="res.groups"><field name="name">Fleet Manager</field></record><record id="rule_own" model="ir.rule"><field name="name">Own vehicles</field><field name="model_id" ref="model_fleet_vehicle_x"/></record></odoo>',
