'addons/fleet_ext/__manifest__.py':"{'name': 'Fleet Extras', 'summary': 'Fuel logs', 'depends': ['fleet_base'], 'data': ['views/ext.xml']}",
'addons/fleet_ext/__init__.py':'from . import models\n',
'addons/fleet_ext/models/ext.py':"from odoo import models, fields\nfrom odoo.addons.fleet_base.models.vehicle import Vehicle\n\nclass VehicleExt(models.Model):\n    _inherit = 'fleet.vehicle.x'\n    fuel_type = fields.Selection([('d', 'Diesel')], default='d')\n\nclass FuelLog(models.Model):\n    _name = 'fleet.fuel.log'\n    vehicle_id = fields.Many2one('fleet.vehicle.x', required=True)\n    liters = fields.Float(required=True)\n",
